// === Tab: spCode.js ===

// www.shaderpark.com

const spCode =  `

	let nscale = 2//input(2, 0, 2);
	let nAmplitude = .0//input(0, 0, .8);
	let hueOffset = .04*nsin(time*.1)//input(.00, 0, .1);
	let rings = 3//input(3, 0, 100);
	let xScale = .01//input(.02, 0, .2)
	setMaxIterations(4) //try changing this to lower and higher values

	noLighting()

	let repeatSpace = (scale, spacing, counts) => {
		spacing *= 2 * scale
		counts -= 1
		const s = getSpace()
		const rounded = floor(s/spacing + 0.5)
		const clamped = vec3(
			clamp(rounded.x, -1*counts.x, counts.x),
			clamp(rounded.y, -1*counts.y, counts.y),
			clamp(rounded.z, -1*counts.z, counts.z)
		)
		displace(spacing*clamped)
		// return instance x, y, z index
		const coordScaled = s / (spacing)
		const index = floor(coordScaled + 0.5)
		return {"index": index, "local": coordScaled-index }
	}

	// simple helper function which repeats space and then calls primitive
	const repBox = shape( (scale, spacing, counts) => {
		const {index, local} = repeatSpace(scale, spacing, counts)
		var s = getSpace();
		let samplePos = index+s * nscale + vec3(0, 0, -time) * .2
		let n1 = nsin((noise(samplePos)) * rings);
		let n2 = nsin((noise(samplePos + hueOffset)) * rings);
		let n3 = nsin((noise(samplePos + hueOffset * 2)) * rings);
		let col = pow(vec3(n1, n2, n3), vec3(4.2));
		//color(hsv2rgb(vec3(n,1,1)))
		color(col)
		sphere(scale.x)
		expand(n1*nAmplitude)
		//box(scale)
	})


	// dimensions of box
	const scale = vec3(xScale, 0.1, 0.1)*0.2
	// extra instances to add in each axis
	const counts = vec3(20, 20, 20)
	// spacing along each axis, in units of scale
	const spacing = vec3(1, 1, 1)*1.4
	// shape to draw at each instance

	rotateY((mouse.x * PI / 2)*.2);
  rotateX((mouse.y * PI / 2)*.2);
	rotateY(PI/2);
	repBox(scale, spacing, counts)

	reset()
	intersect();
	rotateZ(getRayDirection().z*10*sin(time*.1))
	torus(.5, .2)
`;


